import{_ as t,o as e,c as o,a2 as l}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"安装与更新","description":"","frontmatter":{},"headers":[],"relativePath":"zh/app/install.md","filePath":"zh/app/install.md","lastUpdated":1790683574000}'),r={name:"zh/app/install.md"};function i(p,a,s,n,c,d){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="安装与更新" tabindex="-1">安装与更新 <a class="header-anchor" href="#安装与更新" aria-label="Permalink to &quot;安装与更新&quot;">​</a></h1><h2 id="首次安装" tabindex="-1">首次安装 <a class="header-anchor" href="#首次安装" aria-label="Permalink to &quot;首次安装&quot;">​</a></h2><ol><li>在平台网页端进入<strong>下载中心</strong>，选择 Android 下载（也可在<a href="/CoinExchange/zh/app/download">下载 App</a>页扫码下载）</li><li>浏览器下载完成后点击安装包</li><li>首次安装时，安卓系统会提示**「是否允许安装未知来源的应用」**——需要允许，否则无法继续</li></ol><div class="tip custom-block"><p class="custom-block-title">为什么会有这个提示</p><p>这是安卓系统对所有非应用商店渠道安装的统一保护机制，与本 App 无关。允许一次之后，后续更新不会再重复询问。</p></div><h2 id="自动更新" tabindex="-1">自动更新 <a class="header-anchor" href="#自动更新" aria-label="Permalink to &quot;自动更新&quot;">​</a></h2><p>从 v1.0.2 起，App 每次启动会自动检查有没有新版本。</p><h3 id="有新版本时" tabindex="-1">有新版本时 <a class="header-anchor" href="#有新版本时" aria-label="Permalink to &quot;有新版本时&quot;">​</a></h3><p>App 会弹出提示，显示新版本号与这一版更新了什么。</p><ul><li>点**「立即更新」**：App 内显示下载进度，下载完成后自动唤起系统安装器，确认即可完成更新</li><li>点**「稍后再说」**：关闭提示，当天不再打扰，第二天会再提醒一次</li></ul><h3 id="更新会不会丢数据" tabindex="-1">更新会不会丢数据 <a class="header-anchor" href="#更新会不会丢数据" aria-label="Permalink to &quot;更新会不会丢数据&quot;">​</a></h3><p><strong>不会。</strong> 更新是覆盖安装，登录状态与本地设置都会保留，不需要重新登录。</p><h3 id="遇到「重要更新」提示" tabindex="-1">遇到「重要更新」提示 <a class="header-anchor" href="#遇到「重要更新」提示" aria-label="Permalink to &quot;遇到「重要更新」提示&quot;">​</a></h3><p>如果某个版本出现了严重问题，平台可能会把该版本标记为必须更新。这时的更新弹窗<strong>无法关闭</strong>，需要完成更新才能继续使用 App。这种情况很少见，通常意味着旧版本存在会影响你使用或资产安全的问题。</p><h2 id="查看当前版本" tabindex="-1">查看当前版本 <a class="header-anchor" href="#查看当前版本" aria-label="Permalink to &quot;查看当前版本&quot;">​</a></h2><p>打开 App →「我的」→ 页面拉到最下方，会显示当前安装的版本号，如 <code>v1.0.4</code>。</p><div class="tip custom-block"><p class="custom-block-title">反馈问题时</p><p>请把这个版本号一起告诉客服。同一个问题在不同版本上的表现可能完全不同，有版本号能大幅加快排查速度。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>点了更新，下载一直不动？</strong> 检查网络连接。安装包约 44MB，在弱网环境下会比较慢。可以关掉弹窗、连上 Wi-Fi 后重新打开 App 再更新。</p><p><strong>下载完了，但没有弹出安装界面？</strong> 多半是没有授予「允许安装未知来源的应用」权限。可到手机的「设置 → 应用管理」中找到本 App，开启该权限后重试。</p><p><strong>提示「应用未安装」？</strong> 如果你的手机上装过来源不同的同名 App（例如从别处下载的旧包），签名不一致会导致无法覆盖安装。需要先卸载旧版本再安装。</p><div class="warning custom-block"><p class="custom-block-title">卸载会清空数据</p><p>卸载重装后需要重新登录。请确认自己记得账号密码，或先联系客服确认。</p></div>',21)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
